import{z as p,x as A,o as n,c as B,q as o,j as i,D as t,d as l,s,S as d,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"树匹配指令选择","description":"","frontmatter":{"title":"树匹配指令选择","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/tree-pattern-isel.md","filePath":"cs/tree-pattern-isel.md","lastUpdated":1791413859000}'),E={name:"cs/tree-pattern-isel.md"};function c(m,a,u,h,D,g){const r=A("Mermaid");return n(),B("div",null,[a[2]||(a[2]=o('<h1 id="树匹配指令选择" tabindex="-1">树匹配指令选择 <a class="header-anchor" href="#树匹配指令选择" aria-label="Permalink to &quot;树匹配指令选择&quot;">​</a></h1><div class="epigraph"><p>IR 树用指令模板覆盖：动态规划选代价最小覆盖，每个模板对应一条或一组机器指令。</p><footer>—— 据 Aho, Ganapathi and Tjiang, Code Generation Using Tree Matching and Dynamic Programming；龙书 8.9；Appel 整理</footer></div><p>上一课<a href="/cs/critical-path-scheduling">关键路径</a>假定已有机器指令。主干<a href="/cs/instruction-select">指令选择</a>有直觉。缺口是 <strong>BURS/树匹配 + DP</strong>：像 <code>lea</code> 覆盖 <code>base+idx*scale</code>。本课钉覆盖，不写 TableGen 描述语言——下一课。调度在选择之后（或与 DAG 选择交织，如 LLVM ISel）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>朴素：每个 IR 运算一条 RISC。CISC 与寻址模式要模式匹配。树覆盖：叶到根 DP，代价相加。缺口是<strong>最小代价覆盖</strong>，不是着色。</p><p>DAG 选择：公共子表达式使树变 DAG，覆盖更难（可能复制或用寄存器）。</p><h3 id="覆盖不是语法分析的-earley" tabindex="-1">覆盖不是语法分析的 Earley <a class="header-anchor" href="#覆盖不是语法分析的-earley" aria-label="Permalink to &quot;覆盖不是语法分析的 Earley&quot;">​</a></h3><p>虽然都是动态规划，对象是 IR 树 vs 文法。不要把 burg 当 yacc。</p><p><span class="marginnote">Aho–Ganapathi–Tjiang。TWIG、burg、iburg。LLVM SelectionDAG / GlobalISel。Appel 的 Maximal Munch 是贪心对照。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>Maximal Munch：贪心最长匹配，快，非优。DP：每个结点存各非终结符最小代价。生成：按记录的模板吐指令。</p>',11)),(n(),i(d,null,{default:t(()=>[s(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20IR%5B%22IR%20%E6%A0%91%22%5D%20--%3E%20PAT%5B%22%E6%A8%A1%E6%9D%BF%E5%8C%B9%E9%85%8D%22%5D%0A%20%20PAT%20--%3E%20DP%5B%22%E4%BB%A3%E4%BB%B7%20DP%22%5D%0A%20%20DP%20--%3E%20MI%5B%22%E6%9C%BA%E5%99%A8%E6%8C%87%E4%BB%A4%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"与 GVN：先编号减树大小。与立即数：选择时要认 ISA 宽度，否则后期再拆。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[l("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"非法覆盖用 expand（伪指令 → 真指令）。失败则报后端 bug。不要在选择里做全局调度。",-1)),a[6]||(a[6]=e("p",null,[l("代价：延迟、长度、是否破坏标志位。fast-math 可允许 "),e("code",null,"fma"),l(" 模板。")],-1)),a[7]||(a[7]=e("p",null,[l("DP 在每个结点做的事：枚举能盖住该结点的模板，把各覆盖的代价取最小存进 "),e("code",null,"dp[结点][非终结符]"),l("：")],-1)),(n(),i(d,null,{default:t(()=>[s(r,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20N%5B%22%E7%BB%93%E7%82%B9%20Add(Mul(a%2Cb)%2C%20c)%22%5D%20--%3E%20A%5B%22%E8%A6%86%E7%9B%96%E7%94%B2%3A%20lea%20%E6%A8%A1%E6%9D%BF%2C%20%E4%BB%A3%E4%BB%B7%201%22%5D%0A%20%20N%20--%3E%20B%5B%22%E8%A6%86%E7%9B%96%E4%B9%99%3A%20mul%20%2B%20add%2C%20%E4%BB%A3%E4%BB%B7%202%22%5D%0A%20%20A%20--%3E%20M%5B%22dp%5B%E7%BB%93%E7%82%B9%5D%5Breg%5D%20%3D%20min%22%5D%0A%20%20B%20--%3E%20M%0A%20%20M%20--%3E%20OK%5B%22%E5%90%88%E6%B3%95%20%E2%86%92%20%E7%BB%A7%E7%BB%AD%E5%90%91%E6%A0%B9%E7%B4%AF%E5%8A%A0%22%5D%0A%20%20M%20--%3E%20NG%5B%22%E6%97%A0%E5%90%88%E6%B3%95%20%E2%86%92%20expand%20%E6%88%96%E6%8A%A5%E5%90%8E%E7%AB%AF%20bug%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=o('<p><span class="marginnote">数字实例：算 <code>x*8 + y</code>，x86 的 <code>lea rax,[rdi+rsi*8]</code> 一条指令搞定，代价记 1；朴素 RISC 要 <code>slli</code>（左移 3 位）加 <code>add</code> 两条，代价 2。DP 在这个结点取 min 后继续向上，父结点看到的只是一个「代价 1 的加法」。</span></p><p><span class="marginnote">术语翻译：expand 就是「先占位、后兑现」。当 ISA 没有真指令直接实现某个模板的结果时，选择器允许一个伪指令占住代价，随后展开成几条真指令；连伪指令都拼不出来，说明模式表有漏洞——报后端 bug，绝不静默生成错码。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 TableGen 语法。后课默认：树/DAG 覆盖做选择。下一课目标描述：把模板写成可维护的描述。</p><p>也不把指令选择当 SQL 查询选择。</p><p><span class="marginnote">常见误区：初学者容易把树匹配 DP 与语法分析混为一谈。语法分析问「这串符号<strong>能否</strong>归约出文法」（合法性），指令选择问「在能盖满的方案里<strong>哪个最便宜</strong>」（合法性之上的最小代价优化）——前者是门槛，后者才是目标。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>树匹配 + DP（或贪心 munch）覆盖 IR。</li><li>代价含延迟与编码约束。</li><li>DAG 因共享比树难。</li><li>出处：Aho, Ganapathi and Tjiang；龙书 8.9；Appel Maximal Munch。</li></ul>',8))])}const P=p(E,[["render",c]]);export{f as __pageData,P as default};
